import { getCustomer } from './customers.js';
import { invoiceTotals } from './invoices.js';
import { formatEuros } from './money.js';
import { balanceDue } from './payments.js';
import { ok, fail } from './result.js';

/**
 * Render an invoice as plain text for display to customers.
 * @param {object} invoice
 * @returns {{ ok: true, value: string } | { ok: false, error: string }}
 */
export function renderInvoiceText(invoice) {
  // Validate invoice
  if (!invoice || !invoice.customerId) return fail('CUSTOMER_NOT_FOUND');

  // Get customer
  const customer = getCustomer(invoice.customerId);
  if (!customer.ok) return customer;

  // Calculate totals
  const totals = invoiceTotals(invoice);
  if (!totals.ok) return totals;

  // Build invoice text
  const lines = [];

  // First line: invoice number or DRAFT
  lines.push(invoice.number ? invoice.number : 'DRAFT');

  // Customer name
  lines.push(customer.value.name);

  // Line items with discounts
  for (const line of invoice.lines) {
    const total = line.qty * line.unitPrice;
    lines.push(
      `${line.qty}x ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(total)}`
    );

    if (line.discountPercent && line.discountPercent > 0) {
      const discount = Math.round(total * (line.discountPercent / 100));
      lines.push(`  Discount: ${line.discountPercent}% = ${formatEuros(discount)}`);
    }
  }

  // Discount summary
  if (totals.value.discount > 0) {
    lines.push(`Discount: ${formatEuros(totals.value.discount)}`);
  }

  // VAT
  if (totals.value.vat > 0) {
    lines.push(`VAT: ${formatEuros(totals.value.vat)}`);
  }

  // Voucher
  if (totals.value.voucher > 0) {
    lines.push(`Voucher: ${formatEuros(totals.value.voucher)}`);
  }

  // Total
  lines.push(`Total: ${formatEuros(totals.value.total)}`);

  // Due date
  if (invoice.dueDate) {
    lines.push(`Due: ${invoice.dueDate}`);
  }

  // Paid amount
  if (invoice.payments && invoice.payments.length > 0) {
    const totalPaid = invoice.payments.reduce((sum, p) => sum + p.amount, 0);
    lines.push(`Paid: ${formatEuros(totalPaid)}`);
  }

  return ok(lines.join('\n'));
}

