test('renderInvoiceText shows complete invoice with all features', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);
  const withVoucher = applyVoucher(issued.value, { code: 'FALL10', amount: 500 });
  const paid = recordPayment(withVoucher.value, { amount: 5000, date: '2026-10-10' });

  const r = renderInvoiceText(paid.value);
  assert.equal(r.ok, true);
  const text = r.value;

  assert.ok(text.includes('INV-2026-0001'));
  assert.ok(text.includes('Northwind Studio'));
  assert.ok(text.includes('Design work (hour)'));
  assert.ok(text.includes('Discount:'));
  assert.ok(text.includes('VAT:'));
  assert.ok(text.includes('Voucher:'));
  assert.ok(text.includes('Total:'));
  assert.ok(text.includes('Due: 2026-10-21'));
  assert.ok(text.includes('Paid:'));
});
